"""IRA (isaacsim.replicator.agent) config YAML for one capture run.

Plain Python (no Isaac imports) so the GUI can write configs; sim/run_capture.py reads them inside Isaac.
"""
from pathlib import Path

S3_CHARACTERS = "https://omniverse-content-production.s3-us-west-2.amazonaws.com/Assets/Isaac/6.0/Isaac/People/Characters/"
MOTION_LIBRARY = ("https://omniverse-content-staging.s3.us-west-2.amazonaws.com/Assets/Behavior/110.0/Samples/"
                  "Assets/MotionLibrary/Human/HumanMotionLibrary.usd")

TEMPLATE = """\
# Generated by sim/ira_config.py
isaacsim.replicator.agent:
  version: 1.6.0
  seed: {seed}
  # setup_simulation() sets the timeline end time from this; it must outlast the capture.
  simulation_duration: {duration}
  environment:
    base_stage_asset_path: {stage}
  character:
    motion_library_path: {motion}
    groups:
      character_group_00:
        num: {num}
        asset_path: {asset_path}
        routines:
        - wander:
            weight: 1.0
            repeat: {repeat}
            walk:
              speed_range:
              - {speed_min}
              - {speed_max}
              distance_range:
              - {dist_min}
              - {dist_max}
              navigation_areas: []
            idle:
            - animation: idle
              weight: 1.0
              time_range:
              - 0.5
              - 1.5
        colliders:
        - cylinder:
            name: collider_pipeline
"""


def default_characters() -> str:
    return S3_CHARACTERS


def write_config(path: Path, stage: Path, seed: int, num: int, num_scans: int, walk_extent_m: float,
                 speed=(0.8, 1.5), asset_path: str | None = None) -> Path:
    """walk_extent_m: longest side of the walking area; walk legs are sized to fit inside it."""
    duration = max(30.0, num_scans / 10.0 * 2.5)  # 10 Hz scans; generous margin for setup/warm-up
    dist_max = max(1.5, min(8.0, walk_extent_m * 0.9))
    # one repeat = one walk + one idle; enough repeats that nobody runs out of routine mid-capture
    repeat = int(duration / (dist_max / speed[1] + 0.5)) + 2
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(TEMPLATE.format(
        seed=int(seed), duration=float(duration), stage=Path(stage).resolve().as_posix(), motion=MOTION_LIBRARY,
        num=int(num), asset_path=asset_path or default_characters(), repeat=repeat,
        speed_min=speed[0], speed_max=speed[1], dist_min=round(dist_max / 2, 2), dist_max=round(dist_max, 2)))
    return path
